CREATE TABLE IF NOT EXISTS quota (key TEXT PRIMARY KEY, count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS trial_applications (id INTEGER PRIMARY KEY AUTOINCREMENT, created_at TEXT NOT NULL, store_name TEXT NOT NULL CHECK (length(store_name) BETWEEN 1 AND 80), contact_name TEXT NOT NULL CHECK (length(contact_name) BETWEEN 1 AND 40), contact TEXT NOT NULL CHECK (length(contact) BETWEEN 1 AND 120), message TEXT NOT NULL DEFAULT '' CHECK (length(message) <= 400), status TEXT NOT NULL DEFAULT 'new' CHECK (status IN ('new','contacted','accepted','declined','deleted')));
CREATE INDEX IF NOT EXISTS trial_applications_created_at ON trial_applications (created_at);
CREATE TABLE IF NOT EXISTS loop_events (id INTEGER PRIMARY KEY AUTOINCREMENT, day TEXT NOT NULL CHECK (day GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'), product TEXT NOT NULL CHECK (product = 'hitokoto-beta'), kind TEXT NOT NULL CHECK (kind IN ('error','feedback')), screen TEXT NOT NULL CHECK (length(screen) BETWEEN 1 AND 40), version TEXT NOT NULL CHECK (length(version) BETWEEN 1 AND 40), fp TEXT NOT NULL CHECK (length(fp) = 16), error_type TEXT CHECK (error_type IS NULL OR length(error_type) <= 80), frame TEXT CHECK (frame IS NULL OR length(frame) <= 80), category TEXT CHECK (category IS NULL OR length(category) <= 20), text_masked TEXT CHECK (text_masked IS NULL OR (kind = 'feedback' AND screen IN ('lp','create') AND length(text_masked) <= 400)), count INTEGER NOT NULL DEFAULT 1 CHECK (count >= 1), UNIQUE (day, kind, fp));
CREATE INDEX IF NOT EXISTS loop_events_product_day ON loop_events (product, day);
CREATE TABLE IF NOT EXISTS pick_stats (day TEXT NOT NULL CHECK (day GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'), kind TEXT NOT NULL CHECK (kind IN ('general','food','beauty','retail')), topic TEXT NOT NULL CHECK (topic GLOB '[a-z]*' AND length(topic) BETWEEN 1 AND 20), rating TEXT NOT NULL CHECK (rating IN ('good','ok','concern')), detail TEXT NOT NULL DEFAULT '' CHECK (length(detail) <= 20), count INTEGER NOT NULL DEFAULT 1 CHECK (count >= 1), PRIMARY KEY (day, kind, topic, rating, detail));
CREATE TABLE IF NOT EXISTS funnel_times (day TEXT NOT NULL CHECK (day GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'), step TEXT NOT NULL CHECK (step IN ('view','classify','rating','rated','cands','cand','confirm','copy','google','draft','direct')), bucket TEXT NOT NULL CHECK (bucket IN ('0-10','10-20','20-30','30-60','60-120','120+')), count INTEGER NOT NULL DEFAULT 1 CHECK (count >= 1), PRIMARY KEY (day, step, bucket));
CREATE TABLE IF NOT EXISTS stores (sid TEXT PRIMARY KEY CHECK (length(sid) = 22 AND sid NOT GLOB '*[^A-Za-z0-9_-]*'), token_hash TEXT NOT NULL UNIQUE CHECK (length(token_hash) = 64 AND token_hash NOT GLOB '*[^0-9a-f]*'), kind TEXT NOT NULL CHECK (kind IN ('general','food','beauty','retail')), created_day TEXT NOT NULL CHECK (created_day GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'), last_used_day TEXT CHECK (last_used_day IS NULL OR last_used_day GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'));
CREATE TABLE IF NOT EXISTS store_picks (sid TEXT NOT NULL REFERENCES stores (sid), day TEXT NOT NULL CHECK (day GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'), topic TEXT NOT NULL CHECK (topic GLOB '[a-z]*' AND length(topic) BETWEEN 1 AND 20), rating TEXT NOT NULL CHECK (rating IN ('good','ok','concern')), detail TEXT NOT NULL DEFAULT '' CHECK (length(detail) <= 20), count INTEGER NOT NULL DEFAULT 1 CHECK (count >= 1), PRIMARY KEY (sid, day, topic, rating, detail));
CREATE TABLE IF NOT EXISTS store_steps (sid TEXT NOT NULL REFERENCES stores (sid), day TEXT NOT NULL CHECK (day GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'), step TEXT NOT NULL CHECK (step IN ('view','classify','rating','rated','cands','cand','confirm','copy','google','draft','direct','picks')), count INTEGER NOT NULL DEFAULT 1 CHECK (count >= 1), PRIMARY KEY (sid, day, step));
